import {
  CarePlanSuggestion,
  EmotionAnalysis,
  InterventionInfo,
  ProblemAnalysis,
  PsychStatModel,
  RiskAssessment,
  EMOTION_NAMES,
  PROBLEM_CATEGORY_NAMES,
  RISK_LEVEL_NAMES
} from '../types';

export interface ReportQuickSummary {
  emotionLabel: string;
  riskLabel: string;
  problemLabel: string;
  oneLine: string;
  reliabilityPct: number | null;
  reliabilityHint: string;
  actionHint: string | null;
}

export function buildReportQuickSummary(
  emotion: EmotionAnalysis,
  risk: RiskAssessment,
  problem?: ProblemAnalysis,
  statModel?: PsychStatModel,
  carePlan?: CarePlanSuggestion,
  intervention?: InterventionInfo
): ReportQuickSummary {
  const emotionLabel = EMOTION_NAMES[emotion.emotion] || emotion.emotion;
  const riskLabel = RISK_LEVEL_NAMES[risk.level] || risk.level;
  const problemLabel = problem
    ? PROBLEM_CATEGORY_NAMES[problem.category] || problem.category
    : '未分类';

  const reliabilityPct =
    statModel?.compositeScores.modelConfidence ??
    (emotion.confidence > 0 ? Math.round(emotion.confidence * 100) : null);

  let reliabilityHint = '综合本次对话与历史数据的分析可靠程度';
  if (reliabilityPct !== null) {
    if (reliabilityPct < 45) {
      reliabilityHint = '可靠度偏低，结论仅供参考，建议结合自评或寻求专业评估';
    } else if (reliabilityPct < 70) {
      reliabilityHint = '可靠度中等，可结合下方详细报告理解';
    } else {
      reliabilityHint = '可靠度较高，仍不能替代专业诊断';
    }
  }

  const actionHint =
    risk.warningMessage ||
    carePlan?.suggestion?.slice(0, 48) ||
    (intervention ? `建议参考：${intervention.frameworkName}` : null);

  return {
    emotionLabel,
    riskLabel,
    problemLabel,
    oneLine: `${emotionLabel} · ${riskLabel}风险 · ${problemLabel}`,
    reliabilityPct,
    reliabilityHint,
    actionHint
  };
}

export function buildReportCopyText(
  summary: ReportQuickSummary,
  report: string,
  statModel?: PsychStatModel
): string {
  const session = statModel?.sessionIndex ?? statModel?.totalSessions;
  const lines = [
    '【心理港湾 · 咨询摘要】',
    session ? `咨询次数：第 ${session} 次` : '',
    `情绪状态：${summary.emotionLabel}`,
    `风险等级：${summary.riskLabel}`,
    `问题领域：${summary.problemLabel}`,
    summary.reliabilityPct !== null ? `分析可靠度：${summary.reliabilityPct}%` : '',
    summary.actionHint ? `关注提示：${summary.actionHint}` : '',
    '',
    '【详细报告】',
    report.trim()
  ];
  return lines.filter(Boolean).join('\n');
}

export interface CounselorShareContext {
  studentLabel?: string;
  orgName?: string;
  className?: string;
  studentNo?: string;
  allowSchoolTranscriptView?: boolean;
}

/** 供主动发给辅导员的简报：不含完整报告正文，避免与「复制摘要」重复 */
export function buildCounselorShareText(
  summary: ReportQuickSummary,
  statModel?: PsychStatModel,
  ctx?: CounselorShareContext
): string {
  const session = statModel?.sessionIndex ?? statModel?.totalSessions;
  const metrics = statModel
    ? `压力 ${statModel.indices.stress.value} · 焦虑 ${statModel.indices.anxiety.value} · 平稳度 ${statModel.indices.moodStability.value}`
    : null;

  const privacyLine =
    ctx?.allowSchoolTranscriptView === false
      ? '学生未授权学校端查看对话原文，请通过面谈了解情况。'
      : '学生已授权范围内，可在学校端「学生列表」查看档案与告警。';

  const lines = [
    '【心理港湾 · 学生情况简报（供辅导员参考）】',
    `生成时间：${new Date().toLocaleString('zh-CN')}`,
    ctx?.studentLabel ? `学生：${ctx.studentLabel}` : '',
    ctx?.orgName ? `院系：${ctx.orgName}` : '',
    ctx?.className ? `班级：${ctx.className}` : '',
    ctx?.studentNo ? `学号：${ctx.studentNo}` : '',
    session ? `本次为第 ${session} 次系统内咨询` : '',
    `概况：${summary.oneLine}`,
    metrics ? `近期指标：${metrics}` : '',
    summary.reliabilityPct !== null ? `分析可靠度：${summary.reliabilityPct}%（仅供参考）` : '',
    summary.actionHint ? `建议关注：${summary.actionHint}` : '',
    '',
    privacyLine,
    '本简报不含完整咨询记录；详细分析请学生使用「复制摘要」或在学校端查阅授权信息。'
  ];
  return lines.filter(Boolean).join('\n');
}

function excerptReport(report: string, maxLen = 380): string {
  const t = report.replace(/\s+/g, ' ').trim();
  if (t.length <= maxLen) return t;
  return `${t.slice(0, maxLen)}…`;
}

export interface OnePageReportInput {
  summary: ReportQuickSummary;
  report: string;
  statModel?: PsychStatModel;
  carePlan?: CarePlanSuggestion;
  intervention?: InterventionInfo;
  ctx?: CounselorShareContext;
}

/** 一页纸打印 HTML：仅要点与报告摘录，非全文 */
export function buildOnePagePrintHtml(input: OnePageReportInput): string {
  const { summary, report, statModel, carePlan, intervention, ctx } = input;
  const session = statModel?.sessionIndex ?? statModel?.totalSessions;
  const excerpt = excerptReport(report);
  const care = carePlan?.suggestion || summary.actionHint || '—';
  const framework = intervention?.frameworkName;

  const metricRows = statModel
    ? `
    <tr><td>压力</td><td>${statModel.indices.stress.value}</td><td>${statModel.indices.stress.levelText}</td></tr>
    <tr><td>焦虑</td><td>${statModel.indices.anxiety.value}</td><td>${statModel.indices.anxiety.levelText}</td></tr>
    <tr><td>情绪平稳</td><td>${statModel.indices.moodStability.value}</td><td>${statModel.indices.moodStability.levelText}</td></tr>
    <tr><td>心理困扰</td><td>${statModel.indices.distress.value}</td><td>${statModel.indices.distress.levelText}</td></tr>`
    : '';

  const esc = (s: string) =>
    s
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');

  return `<!DOCTYPE html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8" />
  <title>心理港湾 · 咨询一页纸</title>
  <style>
    @page { size: A4; margin: 14mm; }
    * { box-sizing: border-box; }
    body { font-family: "Microsoft YaHei", "PingFang SC", sans-serif; font-size: 11pt; color: #1e293b; line-height: 1.45; margin: 0; }
    h1 { font-size: 16pt; margin: 0 0 4px; color: #4338ca; }
    .meta { font-size: 9pt; color: #64748b; margin-bottom: 12px; }
    .grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-bottom: 12px; }
    .card { border: 1px solid #e2e8f0; border-radius: 8px; padding: 8px 10px; }
    .card label { display: block; font-size: 8pt; color: #64748b; text-transform: uppercase; }
    .card strong { font-size: 12pt; }
    table { width: 100%; border-collapse: collapse; margin: 10px 0; font-size: 10pt; }
    th, td { border: 1px solid #e2e8f0; padding: 6px 8px; text-align: left; }
    th { background: #f8fafc; }
    .section { margin-top: 10px; }
    .section h2 { font-size: 11pt; margin: 0 0 6px; color: #334155; }
    .excerpt { background: #f8fafc; padding: 10px; border-radius: 8px; font-size: 10pt; white-space: pre-wrap; }
    .footer { margin-top: 14px; font-size: 8pt; color: #94a3b8; border-top: 1px solid #e2e8f0; padding-top: 8px; }
  </style>
</head>
<body>
  <h1>心理港湾 · 咨询一页纸</h1>
  <p class="meta">
    ${esc(new Date().toLocaleString('zh-CN'))}
    ${session ? ` · 第 ${session} 次咨询` : ''}
    ${ctx?.studentLabel ? ` · ${esc(ctx.studentLabel)}` : ''}
    ${ctx?.orgName ? ` · ${esc(ctx.orgName)}` : ''}
  </p>
  <div class="grid">
    <div class="card"><label>情绪</label><strong>${esc(summary.emotionLabel)}</strong></div>
    <div class="card"><label>风险</label><strong>${esc(summary.riskLabel)}</strong></div>
    <div class="card"><label>问题</label><strong>${esc(summary.problemLabel)}</strong></div>
  </div>
  ${
    metricRows
      ? `<div class="section"><h2>核心指标</h2><table><thead><tr><th>维度</th><th>分值</th><th>水平</th></tr></thead><tbody>${metricRows}</tbody></table></div>`
      : ''
  }
  <div class="section">
    <h2>关怀建议</h2>
    <p>${esc(care)}</p>
    ${framework ? `<p style="font-size:9pt;color:#64748b">干预框架：${esc(framework)}</p>` : ''}
  </div>
  <div class="section">
    <h2>报告要点摘录（非全文）</h2>
    <div class="excerpt">${esc(excerpt)}</div>
  </div>
  <p class="footer">
    教学展示用途，不能替代专业心理评估。完整报告请使用系统内「复制摘要」或「导出全文」。
    ${summary.reliabilityPct !== null ? ` 可靠度 ${summary.reliabilityPct}%。` : ''}
  </p>
</body>
</html>`;
}
